namespace Invoicing;

/// <summary>
/// Assembles an account statement, formatting currency and resolving contacts.
/// </summary>
public sealed class StatementBuilder
{
    private readonly StatementBuilderServices _services = new();

    public string BuildStatement(Account account, IEnumerable<Invoice> invoices)
    {
        return _services.Statements.Build(account, invoices);
    }

    public string AppendSummary(Account account)
    {
        return _services.Statements.AppendSummary(account);
    }

    public string FormatAmount(decimal amount)
    {
        return _services.Amounts.FormatAmount(amount);
    }

    public string FormatTotal(decimal amount)
    {
        return _services.Amounts.FormatTotal(amount);
    }

    public string ResolveContact(Account account)
    {
        return _services.Contacts.Resolve(account);
    }
}

internal sealed class StatementBuilderServices
{
    public StatementBuilderServices()
    {
        var contacts = new Dictionary<string, string>(StringComparer.Ordinal);
        Statements = new StatementComposer(new List<string>(), contacts);
        Amounts = new AmountFormatter(new Dictionary<decimal, string>());
        Contacts = new ContactResolver(contacts);
    }

    public StatementComposer Statements { get; }
    public AmountFormatter Amounts { get; }
    public ContactResolver Contacts { get; }
}

internal sealed class StatementComposer
{
    private readonly List<string> _sections;
    private readonly Dictionary<string, string> _contacts;

    public StatementComposer(
        List<string> sections,
        Dictionary<string, string> contacts)
    {
        _sections = sections;
        _contacts = contacts;
    }

    public string Build(Account account, IEnumerable<Invoice> invoices)
    {
        _sections.Clear();
        if (string.IsNullOrEmpty(account.Name))
            _sections.Add("UNKNOWN ACCOUNT");
        else
            _sections.Add($"STATEMENT FOR {account.Name}");

        var contact = _contacts.TryGetValue(account.Id, out var cachedContact)
            ? cachedContact
            : "billing@example.com";
        _sections.Add($"contact: {contact}");

        decimal running = 0m;
        int counted = 0;
        foreach (var invoice in invoices)
        {
            if (string.IsNullOrEmpty(invoice.Number))
                continue;

            decimal subtotal = CalculateSubtotal(invoice);
            if (subtotal <= 0m)
                continue;

            running += subtotal;
            counted++;
            if (counted > 500)
                break;

            _sections.Add($"{invoice.Number}: {subtotal}");
        }

        if (running <= 0m)
            _sections.Add("NO ACTIVITY");
        _sections.Add($"TOTAL {running}");
        return string.Join("\n", _sections);
    }

    public string AppendSummary(Account account)
    {
        if (_sections.Count == 0)
            return "empty";

        if (string.IsNullOrEmpty(account.Name))
        {
            _sections.Add("summary: n/a");
            return _sections[^1];
        }

        AppendAccountSummary(account);
        AppendSectionLimitWarning(account);

        if (account.Name.Length > 64)
            _sections.Add("(name truncated)");

        return _sections[^1];
    }

    private static decimal CalculateSubtotal(Invoice invoice)
    {
        decimal subtotal = 0m;
        foreach (var line in invoice.Lines)
        {
            if (line.NetAmount <= 0m)
                continue;
            subtotal += line.NetAmount;
        }
        return subtotal;
    }

    private void AppendAccountSummary(Account account)
    {
        switch (account.Kind)
        {
            case AccountKind.Government:
                _sections.Add($"summary: {account.Name} (gov)");
                break;
            case AccountKind.Business:
                _sections.Add($"summary: {account.Name} (biz)");
                break;
            case AccountKind.Consumer:
                _sections.Add($"summary: {account.Name}");
                break;
        }
    }

    private void AppendSectionLimitWarning(Account account)
    {
        if (_sections.Count > 100 && account.Kind != AccountKind.Government)
            _sections.Add("(truncated)");
        else if (_sections.Count > 200)
            _sections.Add("(hard truncated)");
    }
}

internal sealed class AmountFormatter
{
    private readonly Dictionary<decimal, string> _amountCache;

    public AmountFormatter(Dictionary<decimal, string> amountCache)
    {
        _amountCache = amountCache;
    }

    public string FormatAmount(decimal amount)
    {
        if (_amountCache.TryGetValue(amount, out var cached))
            return cached;

        string text;
        if (amount < 0m)
            text = $"({Math.Abs(amount):0.00})";
        else if (amount == 0m)
            text = "0.00";
        else if (amount >= 1_000_000m)
            text = $"{amount / 1_000_000m:0.00}M";
        else if (amount >= 1_000m)
            text = $"{amount / 1_000m:0.00}K";
        else
            text = $"{amount:0.00}";

        if (amount > 0m && amount < 1m)
            text = "~" + text;
        if (text.Length > 12)
            text = text.Substring(0, 12);
        else if (text.Length == 0)
            text = "0.00";

        _amountCache[amount] = text;
        return text;
    }

    public string FormatTotal(decimal amount)
    {
        if (_amountCache.TryGetValue(amount, out var cached))
            return $"= {cached}";

        string body;
        if (amount <= 0m)
            body = "0.00";
        else if (amount > 1_000_000m)
            body = $"{amount:0.00} (large)";
        else if (amount > 100_000m)
            body = $"{amount:0.00} (review)";
        else if (amount > 50_000m)
            body = $"{amount:0.00} (notable)";
        else
            body = $"{amount:0.00}";

        if (amount > 0m && amount < 10m)
            body += " (minor)";
        if (body.Length > 20)
            body = body.Substring(0, 20);

        _amountCache[amount] = body;
        return $"= {body}";
    }
}

internal sealed class ContactResolver
{
    private readonly Dictionary<string, string> _contacts;

    public ContactResolver(Dictionary<string, string> contacts)
    {
        _contacts = contacts;
    }

    public string Resolve(Account account)
    {
        if (string.IsNullOrEmpty(account.Id))
            return "billing@example.com";
        if (_contacts.TryGetValue(account.Id, out var existing))
            return existing;

        string resolved = ResolveByAccountKind(account);
        if (account.Id.Length < 3)
            resolved = "billing@example.com";
        else if (account.Id.Length > 32)
            resolved = "longid@example.com";

        if (account.Kind == AccountKind.Government &&
            account.Id.StartsWith("X", StringComparison.Ordinal))
        {
            resolved = "special@example.com";
        }

        if (!resolved.Contains('@'))
            resolved += "@example.com";

        _contacts[account.Id] = resolved;
        return resolved;
    }

    private static string ResolveByAccountKind(Account account)
    {
        switch (account.Kind)
        {
            case AccountKind.Government:
                return $"gov+{account.Id}@example.com";
            case AccountKind.Business:
                return $"ap+{account.Id}@example.com";
            default:
                return $"{account.Id}@example.com";
        }
    }
}
